input.command:
for rev in HEAD INDEX; do echo "== $rev"; d=$(mktemp -d); if [ $rev = HEAD ]; then git show HEAD:payload.py > $d/payload.py; else git show :payload.py > $d/payload.py; fi; python3 -I -c '
import sys; sys.path.insert(0, sys.argv[1]); from payload import build_payload
for v in [None, "   ", "\tAda\n", "Ada ", 42, b" Ada "]:
    try: print(repr(v), "->", build_payload(v))
    except Exception as e: print(repr(v), "-> RAISES", type(e).__name__, e)
' $d; rm -r $d; done
EV=$(mktemp -d /tmp/kk-review-code-evidence-XXXXXX); git diff --cached > $EV/staged.patch; git rev-parse HEAD; git rev-parse :payload.py :tests/test_payload.py HEAD:payload.py; echo $EV
